5ji24/f2J3FR4vrAFiiEa4GQ4CRpuYYEQ2bX6d7Av4NGj8dDqJY91eZpnrGLj6XjdFScV7j8oWor
H4thf/x9/H38/Ti//w/+IjYiAFYZAA==
PI_HOST_B64_EOF
}
PI_HOST_EMBEDDED_VERSION="0.20.1"
# <<< END EMBEDDED PI-HOST

PI_HOST_VERSION_FILE="${PI_HOST_APP}/.installed-version"

install_pi_host() {
  [[ -n "$PI_HOST_EMBEDDED_VERSION" ]] || die "no embedded tnode-pi-host (run scripts/embed_pi_host.py)"
  if [[ -s "$PI_HOST_VERSION_FILE" && "$(cat "$PI_HOST_VERSION_FILE")" == "$PI_HOST_EMBEDDED_VERSION" \
        && -d "${PI_HOST_APP}/node_modules/@earendil-works" ]]; then
    info "tnode-pi-host ${PI_HOST_EMBEDDED_VERSION} already installed (snapshot)"
    return 0
  fi
  local stage; stage="$(mktemp -d)"
  _pi_host_b64 | base64 -d | tar xz -C "$stage"
  rm -rf "${PI_HOST_APP}.new"
  mv "$stage/tnode-pi-host" "${PI_HOST_APP}.new"
  rm -rf "$stage"
  chown -R "$TNODE_USER:$TNODE_USER" "${PI_HOST_APP}.new"
  # npm ci: exact versions from the embedded lockfile. TNode packages come
  # vendored (copied after ci, which would prune them).
  sudo -u "$TNODE_USER" -H bash -c "cd '${PI_HOST_APP}.new' && npm ci --omit=dev --no-audit --no-fund >/dev/null && mkdir -p node_modules/@tbrain && cp -R vendor/@tbrain/* node_modules/@tbrain/"
  rm -rf "$PI_HOST_APP"
  mv "${PI_HOST_APP}.new" "$PI_HOST_APP"
  printf '%s' "$PI_HOST_EMBEDDED_VERSION" > "$PI_HOST_VERSION_FILE"
  chown "$TNODE_USER:$TNODE_USER" "$PI_HOST_VERSION_FILE"
  info "tnode-pi-host ${PI_HOST_EMBEDDED_VERSION} installed"
}

# Vault master key (pi-host vault.enc: connector credentials). Sealed with
# systemd-creds and this machine's host key, so a copied vault is useless
# elsewhere; created per node, never in bake mode (cleanup-pre-snapshot-pi.sh
# also wipes the host key). Kept across re-runs: a new key would orphan the
# secrets already stored. Fallback without systemd-creds: a 0400 key file.
VAULT_CRED="/etc/tnode/pi-host-vault.cred"
VAULT_KEYFILE="/etc/tnode/pi-host-vault.key"
VAULT_KEY_UNIT=""
VAULT_KEY_ENV=""
ensure_vault_key() {
  install -d -m 755 /etc/tnode
  if [[ ! -s "$VAULT_CRED" && ! -s "$VAULT_KEYFILE" ]]; then
    if command -v systemd-creds >/dev/null 2>&1 \
       && head -c 32 /dev/urandom | base64 | systemd-creds encrypt --with-key=host --name=vault-key - "$VAULT_CRED" 2>/dev/null; then
      chmod 600 "$VAULT_CRED"
      info "vault key sealed with systemd-creds (host key)"
    else
      rm -f "$VAULT_CRED"
      (umask 077; head -c 32 /dev/urandom | base64 > "$VAULT_KEYFILE")
      chown "$TNODE_USER:$TNODE_USER" "$VAULT_KEYFILE"
      chmod 400 "$VAULT_KEYFILE"
      warn "systemd-creds unavailable — vault key in ${VAULT_KEYFILE} (0400)"
    fi
  fi
  if [[ -s "$VAULT_CRED" ]]; then
    VAULT_KEY_UNIT="LoadCredentialEncrypted=vault-key:${VAULT_CRED}"
  else
    VAULT_KEY_ENV="PI_HOST_VAULT_KEY_FILE=${VAULT_KEYFILE}"
  fi
}

HOST_TOKEN=""
configure_pi_host() {
  local token_file="${PI_HOST_HOME}/token"
  if [[ ! -s "$token_file" ]]; then
    (umask 077; head -c 32 /dev/urandom | base64 | tr -d '/+=\n' > "$token_file")
    chown "$TNODE_USER:$TNODE_USER" "$token_file"
  fi
  HOST_TOKEN="$(cat "$token_file")"
  ensure_vault_key
  (umask 077; cat > "$PI_HOST_ENV" <<ENV
PI_HOST_TOKEN=${HOST_TOKEN}
PI_HOST_HOME=${PI_HOST_HOME}
NODE_ENV=production
${VAULT_KEY_ENV}
ENV
  )
  cat > /etc/systemd/system/tnode-pi-host.service <<UNIT
[Unit]
Description=TNode Pi host (Pi agent harness)
After=network-online.target
Wants=network-online.target

[Service]
User=${TNODE_USER}
WorkingDirectory=${PI_HOST_HOME}
EnvironmentFile=${PI_HOST_ENV}
${VAULT_KEY_UNIT}
ExecStart=$(command -v node) ${PI_HOST_APP}/dist/main.js
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
UNIT
  systemctl daemon-reload
  systemctl enable tnode-pi-host >/dev/null 2>&1
  systemctl restart tnode-pi-host
  if [[ "$AUTO_PAIR" != "1" ]]; then
    # An own-server node opens its ports once the owner links it from the app
    # (until then mintNodeToken answers 409 and the host retries every 30s).
    info "tnode-pi-host started — it goes live when you link the node from the app"
    return 0
  fi
  local i
  for i in $(seq 1 90); do
    ss -ltn 2>/dev/null | grep -q ':18790 ' && { info "tnode-pi-host listening (${i}s)"; return 0; }
    sleep 1
  done
  warn "tnode-pi-host not listening after 90s — see: journalctl -u tnode-pi-host"
}

# ── Main ─────────────────────────────────────────────────────────────────────
ensure_packages
ensure_node
ensure_user

if [[ "$BAKE_MODE" == "1" ]]; then
  ensure_cloudflared_binary
  install_pi_host
  python3 - "${TNODE_HOME}/.pi-baked" <<PY
import json, sys, datetime, subprocess
json.dump({
    "installer": "${TNODE_PI_SETUP_VERSION}",
    "piHost": "${PI_HOST_EMBEDDED_VERSION}",
    "node": subprocess.run(["node", "--version"], capture_output=True, text=True).stdout.strip(),
    "cloudflared": subprocess.run(["/usr/local/bin/cloudflared", "--version"], capture_output=True, text=True).stdout.split()[2],
    "bakedAt": datetime.datetime.now(datetime.timezone.utc).isoformat(),
}, open(sys.argv[1], "w"), indent=2)
PY
  chown "$TNODE_USER:$TNODE_USER" "${TNODE_HOME}/.pi-baked"
  info "bake done: $(tr -d '\n' < "${TNODE_HOME}/.pi-baked")"
  exit 0
fi

ensure_tunnel
ensure_cloudflared
ensure_registration
install_pi_host
configure_pi_host

report_progress_heartbeat "tunnel_ready" "$(python3 -c '
import json, sys
print(json.dumps({"tunnelDomain": sys.argv[1], "tunnelId": sys.argv[2],
                  "gatewayToken": sys.argv[3], "serverUrl": "wss://" + sys.argv[1] + "/ws"}))
' "$TUNNEL_DOMAIN" "$TUNNEL_ID" "$HOST_TOKEN")"
report_progress_heartbeat "chat_sync_registered"
report_progress_heartbeat "pairing_ready"

# True when the node already belongs to an account: a cloud node carries its
# ownerUid, and an own-server node mints a token only once it was linked
# (mintNodeToken answers 409 before that). Re-running the installer on a
# linked node must not print its pairing token again (tnode_server#50).
node_has_owner() {
  python3 - "$SYNC_JSON" <<'PY'
import hashlib, hmac, json, secrets, sys, time, urllib.error, urllib.request
cfg = json.load(open(sys.argv[1]))
if cfg.get("ownerUid") or cfg.get("autoPair"):
    sys.exit(0)
ts, nonce = str(int(time.time() * 1000)), secrets.token_hex(16)
sig = hmac.new(cfg["nodeSecret"].encode(), f'{cfg["nodeId"]}:{ts}:{nonce}:sync_admin'.encode(), hashlib.sha256).hexdigest()
body = json.dumps({"nodeId": cfg["nodeId"], "timestamp": ts, "nonce": nonce, "signature": sig, "scope": "sync_admin"}).encode()
req = urllib.request.Request(cfg["mintUrl"], data=body, headers={"Content-Type": "application/json"})
try:
    urllib.request.urlopen(req, timeout=20)
    sys.exit(0)
except (urllib.error.URLError, OSError):
    sys.exit(1)
PY
}

info "done — node ${NODE_ID} at wss://${TUNNEL_DOMAIN}/ws (harness: pi)"
if [[ "$AUTO_PAIR" != "1" ]] && node_has_owner; then
  info "node already linked to an account — no pairing code shown"
elif [[ "$AUTO_PAIR" != "1" ]]; then
  # The app's "Escanear QR". It carries the node token: only shown to whoever
  # is installing on this server.
  PAIR_URL="tbrain://pair?host=$(python3 -c 'import sys,urllib.parse;print(urllib.parse.quote(sys.argv[1],safe=""))' "wss://${TUNNEL_DOMAIN}/ws")&token=${HOST_TOKEN}"
  info "link it to your account: in the TNode app, Vincular dispositivo → Escanear QR"
  qrencode -t ANSIUTF8 "$PAIR_URL" || true
  info "or Pegar código: ${PAIR_URL}"
fi
